keys=[l.split(' = ',1)[0] for l in open(W+r'\tmp\d064.txt',encoding='utf-8').read().split('\n') if ' = ' in l]
out={}
for k in keys:
    if k in T: out[k]=T[k]; continue
    alt=k.replace('foxablazeaqzl_wiki.wiki.','')
    for kk in T:
        if kk.endswith(alt) or kk.replace('foxablazeaqzl_wiki.wiki.','')==alt: out[k]=T[kk];break
print('keys',len(keys),'out',len(out),[k for k in keys if k not in out])
